48	/**
49	 * Walk's numerals (literals.tex, "Literals").  A numeral evaluates to its
50	 * default, a ZZ32, a ZZ64 or a ZZ by its value, or an RR64 with a radix point,
51	 * as a value that also carries the numeral's four numbers: its digit count,
52	 * the digits after the radix point, its radix, and its digits read as one
53	 * integer.  Where a place fixes a type the numeral converts there from those
54	 * numbers, through that type's coercion from the numeral type, generic over
55	 * the four numbers: the coercion's body runs once with the numbers bound, and
56	 * a site gives one value at each type.  A numeral's own type exists only at
57	 * compile time, so no value has it.  Elsewhere the numeral is its default,
58	 * and a binding keeps the default alone (plain).
59	 */
60	public final class Numerals {
61	
62	    private Numerals() {
63	    }
64	
65	    /** A numeral's value at its default. */
66	    public interface Numeral {
67	        Site site();
68	    }
