70	    /** One numeral of the program: its four numbers, its default, and what it converts to. */
71	    public static final class Site {
72	        final int digits;
73	        final int fractionDigits;
74	        final int radix;
75	        final BigInteger digitValue;
76	        final boolean radixPoint;
77	        /** The numeral's kind: as written, prefix minus on one, or a folded static expression. */
78	        final NumeralNumbers.Kind kind;
79	        /** The signed exact value of an integer numeral; of a radix-point numeral, its numerator over exactDen. */
80	        final BigInteger signed;
81	        /** The denominator of a radix-point numeral's exact value, signed over denomBase^denomPower; one for an integer numeral. */
82	        int denomBase = 10;
83	        int denomPower = 0;
84	        FValue value;
85	        FValue plain;
86	        /** Which float types the exact value rounds to an infinity at: -1 not yet known, 0 none, 1 RR32, 2 RR32 and RR64. */
87	        private int infiniteAt = -1;
88	        private final Map<FType, FValue> converted = new HashMap<FType, FValue>();
89	
90	        Site(NumeralNumbers x, BigInteger signed) {
91	            this.digits = x.n.intValue();
92	            this.fractionDigits = x.m.intValue();
93	            this.radix = x.r.intValue();
94	            this.digitValue = x.v;
95	            this.radixPoint = x.radixPoint;
96	            this.kind = x.kind;
97	            this.signed = signed;
98	        }
