159	    private static final BigInteger INT_MIN = BigInteger.valueOf(Integer.MIN_VALUE);
160	    private static final BigInteger INT_MAX = BigInteger.valueOf(Integer.MAX_VALUE);
161	    private static final BigInteger LONG_MIN = BigInteger.valueOf(Long.MIN_VALUE);
162	    private static final BigInteger LONG_MAX = BigInteger.valueOf(Long.MAX_VALUE);
163	    private static final BigInteger NN32_MAX = BigInteger.ONE.shiftLeft(32).subtract(BigInteger.ONE);
164	    private static final BigInteger NN64_MAX = BigInteger.ONE.shiftLeft(64).subtract(BigInteger.ONE);
