166	    /** The digit part of a numeral's text, before its radix: digit-group separators and the radix point removed. */
167	    private static String digitPart(String text) {
168	        String s = text.replace("'", "").replace(" ", "");
169	        int under = s.indexOf('_');
170	        if (under >= 0) s = s.substring(0, under);
171	        return s.replace(".", "").replace("-", "");
172	    }
