174	    private static int radixOf(String text) {
175	        int under = text.indexOf('_');
176	        if (under < 0) return 10;
177	        try {
178	            return Integer.parseInt(text.substring(under + 1).trim());
179	        }
180	        catch (NumberFormatException ex) {
181	            return 10;
182	        }
183	    }
