185	    /** The value of the integer numeral x at its site. */
186	    public static FValue integer(IntLiteralExpr x) {
187	        synchronized (Numerals.class) {
188	            Site s = sites.get(x);
189	            if (s != null) return s.value;
190	            BigInteger v = x.getIntVal();
191	            s = new Site(NumeralNumbers.of(x), v);
192	            if (v.compareTo(INT_MIN) >= 0 && v.compareTo(INT_MAX) <= 0) {
193	                s.value = new IntNumeral(v.intValue(), s);
194	                s.plain = FInt.make(v.intValue());
195	            } else if (v.compareTo(LONG_MIN) >= 0 && v.compareTo(LONG_MAX) <= 0) {
196	                s.value = new LongNumeral(v.longValue(), s);
197	                s.plain = FLong.make(v.longValue());
198	            } else {
199	                s.value = new BigNumeral(v, s);
200	                s.plain = FBigNum.make(v);
201	            }
202	            sites.put(x, s);
203	            return s.value;
204	        }
205	    }
