207	    /** The value of the numeral with a radix point x at its site. */
208	    public static FValue radixPoint(FloatLiteralExpr x) {
209	        synchronized (Numerals.class) {
210	            Site s = sites.get(x);
211	            if (s != null) return s.value;
212	            NumeralNumbers nn = NumeralNumbers.of(x);
213	            BigInteger v = nn.v;
214	            int r = nn.r.intValue();
215	            int m = nn.m.intValue();
216	            // The exact value as the node holds it, a negated numeral's magnitude negated.
217	            BigInteger den = BigInteger.valueOf(x.getDenomBase()).pow(x.getDenomPower());
218	            BigInteger num = x.getIntPart().multiply(den).add(x.getNumerator());
219	            if (nn.kind == NumeralNumbers.Kind.NEGATED) num = num.abs().negate();
220	            s = new Site(nn, num);
221	            s.denomBase = x.getDenomBase();
222	            s.denomPower = x.getDenomPower();
223	            double d = simpleDoubleArith.numeralToDouble(v, r, m);
224	            if (nn.kind == NumeralNumbers.Kind.NEGATED) d = -d;   // -0.0 keeps its sign
225	            s.value = new FloatNumeral(d, s);
226	            s.plain = FFloat.make(d);
227	            sites.put(x, s);
228	            return s.value;
229	        }
230	    }
