304	    /**
305	     * Which of the float types the exact value of the site's numeral, as
306	     * written or folded, rounds to an infinity at: 0 none, 1 RR32 alone, 2
307	     * RR32 and RR64.
308	     */
309	    private static int infiniteAt(Site s) {
310	        // the answer is one for the site, so a read of it needs no lock
311	        int known = s.infiniteAt;
312	        if (known >= 0) return known;
313	        synchronized (s) {
314	            if (s.infiniteAt < 0) {
315	                BigInteger mag = s.signed.abs();
316	                // a magnitude below 2^127 rounds to a finite float
317	                if (mag.bitLength() <= 127) s.infiniteAt = 0;
318	                else if (!Float.isInfinite(simpleDoubleArith.numeralToFloat(mag, s.denomBase, s.denomPower))) s.infiniteAt = 0;
319	                else s.infiniteAt = Double.isInfinite(simpleDoubleArith.numeralToDouble(mag, s.denomBase, s.denomPower)) ? 2 : 1;
320	            }
321	            return s.infiniteAt;
322	        }
323	    }
324	
325	    /**
326	     * Whether v is a numeral with a radix point, as written or folded, t is
327	     * the library's RR64, the type of v's default, and v's exact value
328	     * rounds to an infinity there: at a place that fixes RR64 such a numeral
329	     * is refused as at any other type (literals.tex, "Literals"), though its
330	     * default is an RR64.  FType.typeMatch asks, so that the place looks for
331	     * a coercion, and inRange finds none.
332	     */
333	    public static boolean roundsToInfinityAsItIs(FType t, FValue v) {
334	        if (!(v instanceof FloatNumeral)) return false;
335	        if (t != v.type() && !(t.getName().equals("RR64") && t == libraryType("RR64"))) return false;
336	        return infiniteAt(((Numeral) v).site()) == 2;
337	    }
