339	    /** RR32's type, which FortressBuiltin declares, as NN32's; or null. */
340	    private static FType rr32Type() {
341	        try {
342	            return FRR32.ZERO.type();
343	        }
344	        catch (RuntimeException ex) {
345	            return null;
346	        }
347	    }
