349	    /**
350	     * Whether the numeral v is inside the range of target, where target is
351	     * one of the library's integer types, or rounds to a finite value there,
352	     * where target is the library's RR64 or RR32 (literals.tex, "Literals": a
353	     * numeral that rounds to an infinity is refused); true for every other
354	     * type.
355	     */
356	    static boolean inRange(FType target, FValue v) {
357	        Site s = ((Numeral) v).site();
358	        String n = target.getName();
359	        if (n.equals("RR64") || n.equals("RR32")) {
360	            if (target != (n.equals("RR32") ? rr32Type() : libraryType(n))) return true;
361	            return infiniteAt(s) < (n.equals("RR64") ? 2 : 1);
362	        }
363	        BigInteger lo, hi;
364	        if (n.equals("ZZ32")) { lo = INT_MIN; hi = INT_MAX; }
365	        else if (n.equals("ZZ64")) { lo = LONG_MIN; hi = LONG_MAX; }
366	        else if (n.equals("NN32")) { lo = BigInteger.ZERO; hi = NN32_MAX; }
367	        else if (n.equals("NN64")) { lo = BigInteger.ZERO; hi = NN64_MAX; }
368	        else return true;
369	        if (target != (n.equals("NN32") ? nn32Type() : libraryType(n))) return true;
370	        BigInteger value = s.radixPoint ? s.digitValue : s.signed;
371	        return value.compareTo(lo) >= 0 && value.compareTo(hi) <= 0;
372	    }
