374	    /** The numeral v converted to target by its coercion c, one value for its site at each type. */
375	    static FValue converted(FValue v, FType target, SingleFcn c) {
376	        Site s = ((Numeral) v).site();
377	        synchronized (s) {
378	            FValue r = s.converted.get(target);
379	            if (r == null) {
380	                r = convert(target, s, c);
381	                s.converted.put(target, r);
382	            }
383	            return r;
384	        }
385	    }
