387	    private static final java.util.Set<String> NUMBER_TYPES = new java.util.HashSet<String>(java.util.Arrays.asList(
388	        "ZZ32", "ZZ64", "NN32", "NN64", "ZZ", "QQ", "RR64", "RR32"));
