395	    /**
396	     * Whether target, a type that is not one of the library's number types,
397	     * declares a coercion from the type of the numeral v.  Its where clause
398	     * may take one numeral and refuse another of the same default, which the
399	     * dispatch caches' key does not tell apart.  A folded static expression
400	     * reaches such a type only as its default, so never by such a coercion.
401	     */
402	    static boolean ownCoercionFrom(FType target, FValue v) {
403	        if (!(v instanceof Numeral) || isStaticExpression(v) || isLibraryNumber(target)) return false;
404	        return !Coercions.numeralCoercions(target, ((Numeral) v).site().radixPoint).isEmpty();
405	    }
