407	    /** Whether v is the value of a folded static expression, not a numeral as written. */
408	    public static boolean isStaticExpression(FValue v) {
409	        return v instanceof Numeral && ((Numeral) v).site().kind == NumeralNumbers.Kind.STATIC;
410	    }
411	
412	    /**
413	     * The coercion to target that is generic over the numeral v's four
414	     * numbers, where its where clause holds at them; or null. For a negative
415	     * constant at a program's own type, also null where the type's prefix
416	     * minus does not apply to the coercion's result. The conversion runs here,
417	     * once for the site and the type, so that a refusal is known.
418	     */
419	    static SingleFcn numeralCoercion(FType target, FValue v) {
420	        Site s = ((Numeral) v).site();
421	        for (FGenericFunction g : Coercions.numeralCoercions(target, s.radixPoint)) {
422	            if (!whereHolds(g.getFnDecl(), numbers(g.getFnDecl(), s))) continue;
423	            synchronized (s) {
424	                if (!s.converted.containsKey(target)) {
425	                    FValue r = convert(target, s, g);
426	                    if (r == null) return null;
427	                    s.converted.put(target, r);
428	                }
429	            }
430	            return g;
431	        }
432	        return null;
433	    }
434	
435	    /**
436	     * The four numbers by the names the coercion's parameter type gives them:
437	     * NaturalNumeral[\n, r, v\] or RadixPointNumeral[\n, m, r, v\]. A numeral
438	     * has no sign: v is the numeral's digits read as one integer.
439	     */
440	    private static Map<String, BigInteger> numbers(FnDecl fd, Site s) {
441	        Map<String, BigInteger> m = new HashMap<String, BigInteger>();
442	        Type pt = (Type) fd.getHeader().getParams().get(0).getIdType().unwrap();
443	        List<StaticArg> args = ((TraitType) pt).getArgs();
444	        BigInteger last = s.digitValue;
445	        BigInteger[] ns = s.radixPoint
446	            ? new BigInteger[] { BigInteger.valueOf(s.digits), BigInteger.valueOf(s.fractionDigits), BigInteger.valueOf(s.radix), last }
447	            : new BigInteger[] { BigInteger.valueOf(s.digits), BigInteger.valueOf(s.radix), last };
448	        for (int i = 0; i < args.size() && i < ns.length; i++) {
449	            StaticArg a = args.get(i);
450	            if (a instanceof IntArg && ((IntArg) a).getIntVal() instanceof IntRef)
451	                m.put(((IntRef) ((IntArg) a).getIntVal()).getName().getText(), ns[i]);
452	        }
453	        return m;
454	    }
