456	    private static BigInteger evalSize(IntExpr e, Map<String, BigInteger> vals) {
457	        if (e instanceof IntBase) return ((IntBase) e).getIntVal().getIntVal();
458	        if (e instanceof IntRef) return vals.get(((IntRef) e).getName().getText());
459	        if (e instanceof IntBinaryOp) {
460	            IntBinaryOp b = (IntBinaryOp) e;
461	            BigInteger l = evalSize(b.getLeft(), vals), r = evalSize(b.getRight(), vals);
462	            if (l == null || r == null) return null;
463	            String op = b.getOp().getText();
464	            if (op.equals("+")) return l.add(r);
465	            if (op.equals("-")) return l.subtract(r);
466	            if (op.equals("^")) return l.pow(r.intValue());
467	            return l.multiply(r);
468	        }
469	        return null;
470	    }
471	
472	    /** Whether each comparison of sizes in the coercion's where clause holds at the four numbers. */
473	    private static boolean whereHolds(FnDecl fd, Map<String, BigInteger> vals) {
474	        Option<WhereClause> w = fd.getHeader().getWhereClause();
475	        if (w.isNone()) return true;
476	        for (WhereConstraint c : w.unwrap().getConstraints()) {
477	            if (!(c instanceof IntConstraint)) continue;
478	            IntConstraint ic = (IntConstraint) c;
479	            BigInteger l = evalSize(ic.getLeft(), vals), r = evalSize(ic.getRight(), vals);
480	            if (l == null || r == null) continue;
481	            int k = l.compareTo(r);
482	            String op = ic.getOp().getText();
483	            boolean ok = op.equals("<") ? k < 0 : op.equals("<=") ? k <= 0 : op.equals(">") ? k > 0
484	                       : op.equals(">=") ? k >= 0 : op.equals("=") ? k == 0 : true;
485	            if (!ok) return false;
486	        }
487	        return true;
488	    }
