490	    /**
491	     * The coercion's body, run once with the four numbers bound as exact
492	     * integers, ZZ values, and the coercion's type's own static parameters
493	     * bound to target's; its parameter is bound to no numeral value, since
494	     * none exists. For a negative constant at a program's own type, the
495	     * type's own prefix minus on the result; null where it does not apply.
496	     */
497	    private static FValue convert(FType target, Site s, SingleFcn c) {
498	        FGenericFunction g = (FGenericFunction) c;
499	        FnDecl fd = g.getFnDecl();
500	        boolean library = isLibraryNumber(target);
501	        // A folded constant at a library type, a negative constant among them,
502	        // converts from its exact value (P-173): only a numeral as written
503	        // reaches a numeral coercion. At a program's type a negative constant
504	        // is the type's own minus on the coercion of its magnitude (P-174).
505	        if (library && s.kind != NumeralNumbers.Kind.WRITTEN) return exactAt(target, s);
506	        boolean minusAfter = s.kind == NumeralNumbers.Kind.NEGATED;
507	        Map<String, BigInteger> vals = numbers(fd, s);
508	        Environment clenv = g.getEnv().extendAt(fd);
509	        List<StaticParam> sps = fd.getHeader().getStaticParams();
510	        if (target instanceof GenericTypeInstance) {
511	            List<FType> targs = ((GenericTypeInstance) target).getTypeParams();
512	            for (int i = 0; i < targs.size() && i < sps.size(); i++) clenv.putType(NodeUtil.getName(sps.get(i)), targs.get(i));
513	        }
514	        for (Map.Entry<String, BigInteger> e : vals.entrySet()) clenv.putValue(e.getKey(), FBigNum.make(e.getValue()));
515	        clenv.bless();
516	        Environment penv = clenv.extendAt(fd);
517	        penv.putValue(NodeUtil.nameString(fd.getHeader().getParams().get(0).getName()), FVoid.V);
518	        penv.bless();
519	        FValue r = new Evaluator(penv).eval(fd.getBody().unwrap());
520	        if (minusAfter) {
521	            Environment within = target.getWithin();
522	            // walk keys a prefix operator by its fixity (OprUtil.fixityDecorator)
523	            FValue minus = within == null ? null : within.getTopLevel().getRootValueNull("prefix -");
524	            if (minus == null && within != null) minus = within.getTopLevel().getRootValueNull("-");
525	            if (!(minus instanceof Fcn)) return null;
526	            try {
527	                r = ((Fcn) minus).applyToArgs(r);
528	            } catch (FortressException ex) {
529	                return null;
530	            }
531	            if (!target.typeMatch(r)) return null;
532	        }
533	        return r;
534	    }
