536	    /**
537	     * A folded constant's exact value at one of the library's number types:
538	     * exactly into an integer type or QQ, by one rounding into RR64 or RR32,
539	     * a negated zero IEEE's negative zero; null for a value the type cannot
540	     * hold exactly, a fraction at an integer type, which the range check and
541	     * the coercions' kinds already exclude.
542	     */
543	    private static FValue exactAt(FType target, Site s) {
544	        BigInteger num = s.signed;
545	        BigInteger den = BigInteger.valueOf(s.denomBase).pow(s.denomPower);
546	        String n = target.getName();
547	        if (n.equals("RR64") || n.equals("RR32")) {
548	            // the magnitude rounded once, then negated, as rounding to nearest is
549	            // symmetric; a negated zero is IEEE's negative zero
550	            BigInteger mag = num.abs();
551	            boolean neg = num.signum() < 0 || (s.kind == NumeralNumbers.Kind.NEGATED && num.signum() == 0);
552	            if (n.equals("RR64")) {
553	                double d = simpleDoubleArith.numeralToDouble(mag, s.denomBase, s.denomPower);
554	                return FFloat.make(neg ? -d : d);
555	            }
556	            float f = simpleDoubleArith.numeralToFloat(mag, s.denomBase, s.denomPower);
557	            return FRR32.make(neg ? -f : f);
558	        }
559	        if (n.equals("QQ")) {
560	            BigInteger g = num.gcd(den);
561	            if (g.signum() == 0) g = BigInteger.ONE;
562	            FValue ratio = library().getRootValueNull("Ratio");
563	            if (!(ratio instanceof Fcn)) return null;
564	            List<FValue> args = new ArrayList<FValue>(2);
565	            args.add(FBigNum.make(num.divide(g)));
566	            args.add(FBigNum.make(den.divide(g)));
567	            return ((Fcn) ratio).applyToArgs(args);
568	        }
569	        if (!den.equals(BigInteger.ONE)) return null;
570	        if (n.equals("ZZ32")) return FInt.make(num.intValue());
571	        if (n.equals("ZZ64")) return FLong.make(num.longValue());
572	        if (n.equals("NN32")) return FNN32.make(num.intValue());
573	        if (n.equals("NN64")) return FNN64.make(num.longValue());
574	        if (n.equals("ZZ")) return FBigNum.make(num);
575	        return null;
576	    }
