578	    /**
579	     * The value a function declared with the return type range answers, where
580	     * its body's value is v: a numeral converted where range fixes a type, as
581	     * a binding converts it, and refused there where it does not convert;
582	     * without a declared return type, its default.
583	     */
584	    public static FValue atReturn(FType range, FValue v) {
585	        if (!hasNumeral(v)) return v;
586	        if (range != null && !range.typeMatch(v)) {
587	            FValue c = Coercions.coerce(range, v);
588	            if (c == null) {
589	                return error(errorMsg("Type mismatch returning ", v, " (type ", v.type(), ") at the declared return type ", range));
590	            }
591	            return c;
592	        }
593	        return plain(v);
594	    }
