596	    /**
597	     * The arguments a generic call infers its static arguments from: each
598	     * numeral at its default, which walk's promotion joins into the
599	     * narrowest type into which every argument coerces (P-74).  Where the
600	     * numerals at the positions of one type parameter include one with a
601	     * radix point, the narrowest default holding them all is an RR64, into
602	     * which an integer numeral beyond ZZ32 converts exactly though its
603	     * default does not coerce: such a numeral is read as a ZZ32 stand-in,
604	     * which promotes with an RR64 to RR64.  The call itself receives the
605	     * numerals, which convert at the instance's parameters.
606	     */
607	    public static List<FValue> forInference(List<FValue> args, GenericFunctionOrMethod g) {
608	        if (!anyNumeral(args)) return args;
609	        List<FValue> res = plain(args);
610	        List<Param> params;
611	        List<StaticParam> sps;
612	        try {
613	            params = g.getParams();
614	            sps = g.getStaticParams();
615	        }
616	        catch (RuntimeException ex) {
617	            return res;
618	        }
619	        if (params == null || sps == null || params.size() != args.size()) return res;
620	        Map<String, List<Integer>> byParam = new HashMap<String, List<Integer>>();
621	        for (int j = 0; j < params.size(); j++) {
622	            if (!(args.get(j) instanceof Numeral)) continue;
623	            Option<TypeOrPattern> ot = params.get(j).getIdType();
624	            if (ot.isNone() || !(ot.unwrap() instanceof VarType)) continue;
625	            String n = NodeUtil.nameString(((VarType) ot.unwrap()).getName());
626	            boolean isStatic = false;
627	            for (StaticParam sp : sps) if (NodeUtil.getName(sp).equals(n)) isStatic = true;
628	            if (!isStatic) continue;
629	            List<Integer> l = byParam.get(n);
630	            if (l == null) byParam.put(n, l = new ArrayList<Integer>());
631	            l.add(j);
632	        }
633	        for (List<Integer> group : byParam.values()) {
634	            if (group.size() < 2) continue;
635	            boolean point = false;
636	            for (int j : group) if (((Numeral) args.get(j)).site().radixPoint) point = true;
637	            if (!point) continue;
638	            for (int j : group) {
639	                Site s = ((Numeral) args.get(j)).site();
640	                if (!s.radixPoint && !(s.plain instanceof FInt)) res.set(j, FInt.make(0));
641	            }
642	        }
643	        return res;
644	    }
