646	    /**
647	     * The dispatch caches' key of an argument list: each argument's type, and
648	     * for a numeral the bottom type, its default's type, its own type and its
649	     * range, so that a numeral and a value of its default type have different
650	     * keys, and so do two numerals of one default that an unsigned type of
651	     * its width holds and does not, and a negative constant and a numeral.
652	     */
653	    public static final class Keys implements EquivalenceClass<List<FValue>, List<FType>> {
654	        public int compare(List<FValue> x, List<FType> y) {
655	            int k = 0;
656	            int ly = y.size();
657	            for (FValue v : x) {
658	                if (v instanceof Numeral) {
659	                    int c = cmp(BottomType.ONLY, y, k++, ly);
660	                    if (c != 0) return c;
661	                    c = cmp(v.type(), y, k++, ly);
662	                    if (c != 0) return c;
663	                    c = cmp(numeralKey(v), y, k++, ly);
664	                    if (c != 0) return c;
665	                    c = cmp(rangeKey(v), y, k++, ly);
666	                    if (c != 0) return c;
667	                } else {
668	                    int c = cmp(keyType(v), y, k++, ly);
669	                    if (c != 0) return c;
670	                }
671	            }
672	            return k < ly ? -1 : 0;
673	        }
674	
675	        private static int cmp(FType t, List<FType> y, int k, int ly) {
676	            if (k >= ly) return 1;
677	            return t.compareTo(y.get(k));
678	        }
679	
680	        public int compareRightKeys(List<FType> x, List<FType> y) {
681	            return FValue.asTypesList.compareRightKeys(x, y);
682	        }
683	
684	        public int compareLeftKeys(List<FValue> x, List<FValue> y) {
685	            return compareRightKeys(translate(x), translate(y));
686	        }
687	
688	        public List<FType> translate(List<FValue> x) {
689	            List<FType> l = new ArrayList<FType>(x.size());
690	            for (FValue v : x) {
691	                if (v instanceof Numeral) {
692	                    l.add(BottomType.ONLY);
693	                    l.add(v.type());
694	                    l.add(numeralKey(v));
695	                    l.add(rangeKey(v));
696	                } else l.add(keyType(v));
697	            }
698	            return l;
699	        }
700	    }
701	
702	    public static final Keys keys = new Keys();
