709	    /**
710	     * Whether the integer numeral v lies in the range of the unsigned type of
711	     * its default's width, NN32 for a ZZ64 default and NN64 for a ZZ default,
712	     * as the bottom type, else the top type; and for a numeral that rounds to
713	     * an infinity at RR32 alone the void type, at RR32 and RR64 the range
714	     * type: the parts of a numeral's dispatch that its default's type does
715	     * not fix (inRange).  For a negative integer constant, which no unsigned
716	     * type holds whatever its width, the pair of that key.
717	     */
718	    private static FType rangeKey(FValue v) {
719	        Site s = ((Numeral) v).site();
720	        int inf = infiniteAt(s);
721	        FType key;
722	        if (inf > 0) key = inf == 1 ? FTypeVoid.ONLY : FTypeRange.ONLY;
723	        else {
724	            BigInteger d = s.digitValue;
725	            boolean fits = v instanceof LongNumeral ? d.compareTo(NN32_MAX) <= 0
726	                           : v instanceof BigNumeral ? d.compareTo(NN64_MAX) <= 0 : true;
727	            key = fits ? BottomType.ONLY : FTypeTop.ONLY;
728	        }
729	        if (s.radixPoint || s.signed == null || s.signed.signum() >= 0) return key;
730	        List<FType> pair = new ArrayList<FType>(2);
731	        pair.add(key);
732	        pair.add(key);
733	        return FTypeTuple.make(pair);
734	    }
